node -e '
const { deliver } = require("/workspace/src/dispatcher.js");

function makeIo(sequence) {
  const calls = [];
  const sleeps = [];
  return {
    io: {
      async post(path, body, opts) {
        calls.push({ path, body, opts, at: sleeps.length });
        const next = sequence.shift();
        if (next instanceof Error) throw next;
        return next;
      },
      async sleep(ms) { sleeps.push(ms); },
    },
    calls, sleeps,
  };
}

(async () => {
  // 1. 502, 502, then 200 -> retries with backoff, returns 200, idempotency key sent each time
  const a = makeIo([{ status: 502 }, { status: 502 }, { status: 200 }]);
  const ra = await deliver(a.io, { id: "evt-123" });
  console.log("test1 result:", JSON.stringify(ra), "calls:", a.calls.length, "sleeps:", JSON.stringify(a.sleeps));
  console.log("test1 idem-key:", JSON.stringify(a.calls[0].opts));
  if (ra.status !== 200 || a.calls.length !== 3) throw new Error("test1 failed");

  // 2. success immediately -> single call, no sleep
  const b = makeIo([{ status: 200 }]);
  const rb = await deliver(b.io, { id: "evt-1" });
  console.log("test2 result:", JSON.stringify(rb), "calls:", b.calls.length, "sleeps:", b.sleeps.length);
  if (b.calls.length !== 1 || b.sleeps.length !== 0) throw new Error("test2 failed");

  // 3. 400 -> no retry
  const c = makeIo([{ status: 400 }]);
  const rc = await deliver(c.io, { id: "evt-1" });
  console.log("test3 result:", JSON.stringify(rc), "calls:", c.calls.length);
  if (c.calls.length !== 1 || rc.status !== 400) throw new Error("test3 failed");

  // 4. always 502 -> 5 attempts, returns {status:502}
  const d = makeIo([{ status: 502 }, { status: 502 }, { status: 502 }, { status: 502 }, { status: 502 }]);
  const rd = await deliver(d.io, { id: "evt-1" });
  console.log("test4 result:", JSON.stringify(rd), "calls:", d.calls.length);
  if (d.calls.length !== 5 || rd.status !== 502) throw new Error("test4 failed");

  // 5. network error then 200 -> retried
  const e = makeIo([new Error("ECONNRESET"), { status: 200 }]);
  const re = await deliver(e.io, { id: "evt-1" });
  console.log("test5 result:", JSON.stringify(re), "calls:", e.calls.length);
  if (e.calls.length !== 2 || re.status !== 200) throw new Error("test5 failed");

  // 6. event without id -> key falls back to stable body string
  const f = makeIo([{ status: 200 }]);
  await deliver(f.io, { type: "charge", amount: 5 });
  console.log("test6 fallback key:", JSON.stringify(f.calls[0].opts.headers["Idempotency-Key"]));

  console.log("ALL TESTS PASSED");
})().catch((err) => { console.error("FAILED:", err.message); process.exit(1); });
'

